<?php
require_once __DIR__.'/../config.php';require_admin();$pageTitle='Subjects & categories';
if(is_post()){verify_csrf();$kind=$_POST['kind']??'';$action=$_POST['action']??'';$name=posted_string('name',120);$description=posted_string('description',500);$id=valid_id($_POST['id']??0);$table=$kind==='subject'?'subjects':($kind==='category'?'categories':'');if(!$table)set_flash('error','Invalid item type.');elseif($action==='add'){if(mb_strlen($name)<2)set_flash('error','Name must be at least 2 characters.');else{try{if($table==='subjects')$pdo->prepare('INSERT INTO subjects(name,description) VALUES(?,?)')->execute([$name,$description]);else $pdo->prepare('INSERT INTO categories(name) VALUES(?)')->execute([$name]);set_flash('success','Item added.');}catch(PDOException $e){set_flash('error','That name already exists or is in use.');}}}elseif($action==='delete'){try{$pdo->prepare("DELETE FROM {$table} WHERE id=?")->execute([$id]);set_flash('success','Item deleted.');}catch(PDOException $e){set_flash('error','Cannot delete this item while resources or groups still reference it.');}}redirect('subjects.php');}
$subjects=$pdo->query('SELECT s.*,(SELECT COUNT(*) FROM resources r WHERE r.subject_id=s.id) resource_count FROM subjects s ORDER BY name')->fetchAll();$categories=$pdo->query('SELECT c.*,(SELECT COUNT(*) FROM resources r WHERE r.category_id=c.id) resource_count FROM categories c ORDER BY name')->fetchAll();require __DIR__.'/../includes/admin_header.php';?>
<div class="grid-2"><section class="panel"><h2>Subjects</h2><p>Subjects organize resources, questions, and groups.</p><form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="subject"><input type="hidden" name="action" value="add"><div class="form-group"><label for="subject_name">Subject name</label><input id="subject_name" name="name" required></div><div class="form-group"><label for="subject_description">Description (optional)</label><input id="subject_description" name="description"></div><button class="btn btn-primary btn-small">Add subject</button></form><div class="separator"></div><?php foreach($subjects as $s): ?><div class="toolbar"><div><strong><?= e($s['name']) ?></strong><div class="small-muted"><?= (int)$s['resource_count'] ?> resources</div></div><form method="post" data-confirm="Delete this subject? This will fail if resources or groups still use it."><?= csrf_field() ?><input type="hidden" name="kind" value="subject"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="btn btn-danger btn-small">Delete</button></form></div><?php endforeach; ?></section>
<section class="panel"><h2>Resource categories</h2><p>Categories help students distinguish notes, past papers, and summaries.</p><form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="category"><input type="hidden" name="action" value="add"><div class="form-group"><label for="category_name">Category name</label><input id="category_name" name="name" required></div><button class="btn btn-primary btn-small">Add category</button></form><div class="separator"></div><?php foreach($categories as $c): ?><div class="toolbar"><div><strong><?= e($c['name']) ?></strong><div class="small-muted"><?= (int)$c['resource_count'] ?> resources</div></div><form method="post" data-confirm="Delete this category? This will fail if resources still use it."><?= csrf_field() ?><input type="hidden" name="kind" value="category"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="btn btn-danger btn-small">Delete</button></form></div><?php endforeach; ?></section></div>
<?php require __DIR__.'/../includes/admin_footer.php';?>
